import Link from "next/link";
import { Arrow, Card, Container, Em, PageHeader } from "@/components/ui";
import { getFilmRepository } from "@/lib/data";
import type { Film } from "@/lib/types";

export const dynamic = "force-dynamic";

export const metadata = { title: "Collections" };

// Hand-curated shelves — each defined by a cinematic quality, not a genre.
// (Static ids for now; later these could be computed from the corpus or
// generated by the exploration engine.)
const COLLECTIONS: { name: string; desc: string; ids: string[] }[] = [
  {
    name: "Slow-burn dread",
    desc: "Tension that accumulates instead of erupting. No jump scares required.",
    ids: [
      "the-witch-2015",
      "the-lighthouse-2019",
      "possum-2018",
      "picnic-at-hanging-rock-1975",
      "enemy-2013",
    ],
  },
  {
    name: "Meditative sci-fi",
    desc: "The cosmos as an interior space — patient, philosophical, near-wordless.",
    ids: [
      "stalker-1979",
      "solaris-1972",
      "2001-a-space-odyssey-1968",
      "blade-runner-2049-2017",
      "under-the-skin-2013",
    ],
  },
  {
    name: "Neon loneliness",
    desc: "Cities after dark and the people who stay awake in them.",
    ids: [
      "lost-in-translation-2003",
      "drive-2011",
      "nightcrawler-2014",
      "in-the-mood-for-love-2000",
      "blade-runner-2049-2017",
    ],
  },
  {
    name: "Unresolved",
    desc: "Mysteries that withhold their answers — the ambiguity is the point.",
    ids: [
      "picnic-at-hanging-rock-1975",
      "zodiac-2007",
      "annihilation-2018",
      "enemy-2013",
      "the-thing-1982",
    ],
  },
];

export default async function CollectionsPage() {
  const catalog = await getFilmRepository().listFilms();
  const byId = new Map(catalog.map((f) => [f.id, f]));

  return (
    <Container className="pb-24">
      <PageHeader
        title={
          <>
            Film collections by <Em>mood</Em>
          </>
        }
        lead="Hand-picked groups of films that share a quality, not a genre. It is the same idea the search uses, put together by hand."
      />

      <div className="grid gap-4 md:grid-cols-2">
        {COLLECTIONS.map((c) => {
          const items = c.ids
            .map((id) => byId.get(id))
            .filter((f): f is Film => !!f);
          return (
            <Card key={c.name} className="p-6">
              <div className="flex items-baseline justify-between gap-4">
                <h2 className="font-display text-2xl">{c.name}</h2>
                <span className="shrink-0 text-xs text-fg-faint">
                  {items.length} films
                </span>
              </div>
              <p className="mt-1.5 text-sm leading-relaxed text-fg-subtle">
                {c.desc}
              </p>
              <ul className="mt-5 divide-y divide-line border-t border-line">
                {items.map((f) => (
                  <li key={f.id}>
                    <Link
                      href={`/film/${f.id}`}
                      className="group flex items-center justify-between gap-4 py-2.5 text-sm text-fg-muted transition-colors hover:text-accent"
                    >
                      <span>
                        {f.metadata.title}
                        <span className="ml-2 text-fg-faint">
                          {f.metadata.year}
                        </span>
                      </span>
                      <span className="text-fg-faint group-hover:text-accent">
                        <Arrow />
                      </span>
                    </Link>
                  </li>
                ))}
              </ul>
            </Card>
          );
        })}
      </div>
    </Container>
  );
}
